# Every preview suffix found in a survey of MAST, plus an ACS "_large" preview, which
# depicts no archived FITS product. Previews of images, from the imaging instruments ACS
# ("j"), WFC3 ("i"), NICMOS ("n"), WFPC ("w"), WFPC2 ("u"), and FOC ("x"), come from
# picmaker, not MAST; previews of spectra, from STIS ("o"), FOS ("y"), GHRS ("z"), and
# COS ("l"), come from MAST.
@pytest.mark.parametrize('filename,accepted', [
    ('j9xx01abq_raw.jpg', False),
    ('j9xx01abq_flt.jpg', False),
    ('j9xx01abq_flc.jpg', False),
    ('j9xx01abq_drz.jpg', False),
    ('j9xx01abq_drc.jpg', False),
    ('idxx01abq_drz.jpg', False),
    ('n4xx01abq_cal.jpg', False),
    ('n4xx01abq_mos.jpg', False),
    ('w0xx0101t_c0f.jpg', False),
    ('u2xx0101t_c0f.jpg', False),
    ('u2xx0101t_d0f.jpg', False),
    ('u2xx0101t_drw.jpg', False),
    ('x0xx0101t_d0f.jpg', False),
    ('y0xx0101t_c0f.jpg', True),
    ('z0xx0101t_c0f.jpg', True),
    ('o4xx01abq_x1d.png', True),
    ('o4xx01abq_sx1.png', True),
    ('lbxx01abq_x1d.png', True),
    ('lbxx01abq_x1dsum.png', True),
    ('lbxx01abq_x1dsum4.png', True),
    ('j9xx01abq_drz_large.jpg', False),
])
def test_is_accepted_instrument_suffix_for_previews(filename, accepted):
    row = {'obs_id': filename.partition('_')[0],
           'productSubGroupDescription': '--',
           'productFilename': filename}
    assert bool(query_utils.is_accepted_instrument_suffix(row)) is accepted


def test_is_accepted_browse_suffix():
    # Non-imaging instruments and STIS spectra use MAST previews
    assert is_accepted_browse_suffix('c0f', 'GHRS')
    assert is_accepted_browse_suffix('c0f', 'FOS')
    assert is_accepted_browse_suffix('x1dsum', 'COS')
    assert is_accepted_browse_suffix('x1d', 'STIS')
    assert is_accepted_browse_suffix('sx1', 'STIS')
    assert not is_accepted_browse_suffix('x1dsum_large', 'COS')
    # Imaging instruments' previews come from picmaker, so none of their MAST previews is
    # archived, whatever the suffix.
    for (instrument_id, suffixes) in PICMAKER_BROWSE_SUFFIXES.items():
        for suffix in suffixes + ('c0f', 'd0f', 'drw', 'drz_large'):
            assert not is_accepted_browse_suffix(suffix, instrument_id)


def test_picmaker_browse_tables():
    # Every imaging instrument, and no non-imaging one, gets picmaker previews, all made
    # with the same options.
    assert set(PICMAKER_BROWSE_SUFFIXES) == {'ACS', 'FOC', 'NICMOS', 'STIS', 'WFC3',
                                             'WFPC', 'WFPC2'}
    assert not set(PICMAKER_BROWSE_SUFFIXES) & NON_IMAGING_INSTRUMENTS
    assert PICMAKER_BROWSE_OPTIONS == {'mosaic': True, 'footprint': 7,
                                       'percentiles': (0.01, 99.99),
                                       'mask_ranges': (0, 0)}
    for (instrument_id, suffixes) in PICMAKER_BROWSE_SUFFIXES.items():
        assert set(suffixes) <= ACCEPTED_SUFFIXES[instrument_id]


def _touch(path):
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, 'wb') as f:
        f.write(b'\xff\xd8\xff\xd9')    # bytes need not form a valid image here


def _basename_dict(fullpath, instrument_id):
    ipppssoot, _, suffix = os.path.basename(fullpath).partition('.')[0].partition('_')
    return {'fullpath': fullpath, 'ipppssoot': ipppssoot, 'suffix': suffix,
            'instrument_id': instrument_id,
            'hst_dictionary': {'hst_proposal_id': 5167}}


def test_get_browse_lids_finds_preview_beside_fits(tmp_path):
    fits = str(tmp_path / 'j9xx01abq_drz.fits')
    _touch(fits)
    assert get_browse_lids(_basename_dict(fits, 'ACS')) == []

    _touch(str(tmp_path / 'j9xx01abq_drz.jpg'))
    _touch(str(tmp_path / 'j9xx01abq_flt.jpg'))     # a different product's preview
    assert get_browse_lids(_basename_dict(fits, 'ACS')) == [
        'urn:nasa:pds:hst_05167:browse_acs_drz:j9xx01abq'
    ]


def test_get_browse_lids_keeps_extended_suffix_in_lid(tmp_path):
    for suffix, prod_id in (('x1dsum', 'ld8x01010'), ('x1dsum3', 'ld8x010103')):
        fits = str(tmp_path / f'ld8x01010_{suffix}.fits')
        _touch(fits)
        _touch(str(tmp_path / f'ld8x01010_{suffix}.png'))
        assert get_browse_lids(_basename_dict(fits, 'COS')) == [
            f'urn:nasa:pds:hst_05167:browse_cos_x1dsum:{prod_id}'
        ]


def test_get_browse_lids_finds_preview_in_sibling_browse_collection(tmp_path):
    # The staging and bundle layout: <program>/<collection>/visit_<ss>/<file>.
    fits = str(tmp_path / 'hst_05167' / 'data_wfpc2_c0m' / 'visit_04' / 'u2xx0401t_c0m.fits')
    _touch(fits)
    assert get_browse_lids(_basename_dict(fits, 'WFPC2')) == []

    for collection, name in (('browse_wfpc2_c0m', 'u2xx0401t_c0m.jpg'),
                             ('browse_wfpc2_d0m', 'u2xx0401t_d0m.jpg'),   # other product
                             ('browse_wfpc2_c0m', 'u2xx0402t_c0m.jpg')):  # other obs
        _touch(str(tmp_path / 'hst_05167' / collection / 'visit_04' / name))
    _touch(str(tmp_path / 'hst_05167' / 'browse_wfpc2_c0m' / 'visit_05' /
               'u2xx0401t_c0m.jpg'))                                        # other visit
    assert get_browse_lids(_basename_dict(fits, 'WFPC2')) == [
        'urn:nasa:pds:hst_05167:browse_wfpc2_c0m:u2xx0401t',
    ]


def test_get_browse_lids_ignores_mast_wfpc2_previews(tmp_path):
    fits = str(tmp_path / 'u2xx0101t_c0m.fits')
    _touch(fits)
    _touch(str(tmp_path / 'u2xx0101t_c0f.jpg'))
    _touch(str(tmp_path / 'u2xx0101t_drw.jpg'))
    assert get_browse_lids(_basename_dict(fits, 'WFPC2')) == []


def _use_tmp_staging(tmp_path, monkeypatch):
    """Point the prepare and label modules at a staging tree under tmp_path."""
    def fake_program_dir_path(proposal_id, visit=None, root_dir='staging'):
        path = str(tmp_path / f'hst_{int(proposal_id):05d}')
        return path + (f'/visit_{visit}' if visit else '')

    monkeypatch.setattr(prepare_module, 'get_program_dir_path', fake_program_dir_path)
    monkeypatch.setattr(label_module, 'get_program_dir_path', fake_program_dir_path)


def test_prepare_browse_products_files_previews_under_mast_names(tmp_path, monkeypatch):
    _use_tmp_staging(tmp_path, monkeypatch)

    download_dir = tmp_path / 'hst_05167' / 'visit_01' / 'mastDownload' / 'HST'
    for name in ('o4xx01abq/o4xx01abq_x1d.png',
                 'j9xx01abq/j9xx01abq_drz.jpg',
                 'u2xx0101t/u2xx0101t_c0f.jpg',
                 'u2xx0101t/u2xx0101t_drw.jpg',
                 'ld8x01010/ld8x01010_x1dsum_large.png',
                 'ld8x01010/ld8x01010_x1dsum1.png'):
        _touch(str(download_dir / name))

    # File the previews, then label them, as the pipeline does.
    prepare_module.prepare_browse_products(5167, '01')
    label_module.label_hst_visit(5167, '01')

    staging = tmp_path / 'hst_05167'
    assert sorted(os.listdir(staging / 'browse_stis_x1d' / 'visit_01')) == [
        'o4xx01abq_x1d.png', 'o4xx01abq_x1d.xml'
    ]
    assert sorted(os.listdir(staging / 'browse_cos_x1dsum' / 'visit_01')) == [
        'ld8x01010_x1dsum1.png', 'ld8x01010_x1dsum1.xml'
    ]

    # No collection name carries the old "mast" prefix.
    assert not any('mast' in name for name in os.listdir(staging))

    # Neither the "_large" preview, which depicts no archived FITS product, nor the MAST
    # previews of images, superseded by picmaker's, is filed; they are left in the inbox.
    assert sorted(name for name in os.listdir(staging) if name.startswith('browse_')) == [
        'browse_cos_x1dsum', 'browse_stis_x1d'
    ]
    inbox_files = [name for (_, _, names) in os.walk(staging / 'visit_01')
                   for name in names]
    assert sorted(inbox_files) == ['j9xx01abq_drz.jpg', 'ld8x01010_x1dsum_large.png',
                                   'u2xx0101t_c0f.jpg', 'u2xx0101t_drw.jpg']


def _write_wfpc2_fits(path):
    """Write a small WFPC2 file in the multi-extension layout of a c0m or d0m file: an
    empty PRIMARY HDU and one 32x32 SCI extension per detector."""
    os.makedirs(os.path.dirname(path), exist_ok=True)
    primary = pyfits.PrimaryHDU()
    primary.header['TELESCOP'] = 'HST'
    primary.header['INSTRUME'] = 'WFPC2'
    primary.header['FILTNAM1'] = 'F555W'
    hdus = [primary]
    rng = np.random.default_rng(1)
    for detector in range(1, 5):
        sci = pyfits.ImageHDU((rng.random((32, 32)) * 100 * detector).astype('float32'),
                              name='SCI')
        sci.header['DETECTOR'] = detector
        hdus.append(sci)
    pyfits.HDUList(hdus).writeto(path)


def test_prepare_browse_products_generates_wfpc2_mosaics(tmp_path, monkeypatch):
    _use_tmp_staging(tmp_path, monkeypatch)
    staging = tmp_path / 'hst_05167'
    download_dir = staging / 'visit_01' / 'mastDownload' / 'HST' / 'u2xx0101t'
    for suffix in ('c0m', 'd0m', 'c1m'):
        _write_wfpc2_fits(str(download_dir / f'u2xx0101t_{suffix}.fits'))

    prepare_module.prepare_browse_products(5167, '01')

    # One mosaic of the four 32x32 detectors for each of c0m and d0m; none for c1m.
    for suffix in ('c0m', 'd0m'):
        browse_dir = staging / f'browse_wfpc2_{suffix}' / 'visit_01'
        assert os.listdir(browse_dir) == [f'u2xx0101t_{suffix}.jpg']
        with Image.open(browse_dir / f'u2xx0101t_{suffix}.jpg') as image:
            assert image.size == (64, 64)
    assert not (staging / 'browse_wfpc2_c1m').exists()

    # Labeling links each mosaic to its data product, and the data product to it.
    label_browse_collection_directory(str(staging / 'browse_wfpc2_c0m'), 5167)
    root = ET.parse(staging / 'browse_wfpc2_c0m' / 'visit_01' / 'u2xx0101t_c0m.xml')
    lids = [e.text for e in root.iterfind('.//pds:logical_identifier', PDS4_NS)]
    assert lids == ['urn:nasa:pds:hst_05167:browse_wfpc2_c0m:u2xx0101t']
    refs = [e.text for e in root.iterfind('.//pds:lidvid_reference', PDS4_NS)]
    assert refs == ['urn:nasa:pds:hst_05167:data_wfpc2_c0m:u2xx0101t::1.0']
    fits = str(staging / 'data_wfpc2_c0m' / 'visit_01' / 'u2xx0101t_c0m.fits')
    assert get_browse_lids(_basename_dict(fits, 'WFPC2')) == [
        'urn:nasa:pds:hst_05167:browse_wfpc2_c0m:u2xx0101t',
    ]


def test_generate_picmaker_browse_products_options_and_reruns(tmp_path, monkeypatch):
    _use_tmp_staging(tmp_path, monkeypatch)
    staging = tmp_path / 'hst_05167'
    for name in ('u2xx0101t_c0m.fits', 'u2xx0102t_c0m.fits', 'u2xx0103t_c0m.fits'):
        _touch(str(staging / 'data_wfpc2_c0m' / 'visit_01' / name))
    _touch(str(staging / 'data_wfpc2_c0m' / 'visit_01' / 'u2xx0101t_c0m.xml'))
    # An existing preview is kept
    _touch(str(staging / 'browse_wfpc2_c0m' / 'visit_01' / 'u2xx0102t_c0m.jpg'))

    calls = []
    def fake_picmaker(**options):
        calls.append(options)
        (fits_path,) = options['files']
        if 'u2xx0103t' in fits_path:
            raise ValueError('unreadable')
        name = os.path.basename(fits_path).replace('.fits', '.jpg')
        _touch(os.path.join(options['directory'], name))

    monkeypatch.setattr(prepare_module, 'picmaker', fake_picmaker)
    assert prepare_module.generate_picmaker_browse_products(5167, '01') == 1

    # Called once for each FITS file without a preview, with the WFPC2 options
    assert [os.path.basename(c['files'][0]) for c in calls] == ['u2xx0101t_c0m.fits',
                                                                 'u2xx0103t_c0m.fits']
    for options in calls:
        assert options['mosaic'] is True
        assert options['footprint'] == 7
        assert options['percentiles'] == (0.01, 99.99)
        assert options['mask_ranges'] == (0, 0)
        assert options['extension'] == 'jpg'
        assert options['directory'] == str(staging / 'browse_wfpc2_c0m' / 'visit_01')
    assert sorted(os.listdir(staging / 'browse_wfpc2_c0m' / 'visit_01')) == [
        'u2xx0101t_c0m.jpg', 'u2xx0102t_c0m.jpg'
    ]

    # A rerun generates only what is still missing
    calls.clear()
    assert prepare_module.generate_picmaker_browse_products(5167, '01') == 0
    assert [os.path.basename(c['files'][0]) for c in calls] == ['u2xx0103t_c0m.fits']


def test_browse_labels_are_named_after_each_image(tmp_path):
    collection_dir = tmp_path / 'browse_cos_x1dsum'
    visit_dir = collection_dir / 'visit_01'
    for name in ('ld8x01010_x1dsum.png', 'ld8x01010_x1dsum1.png'):
        _touch(str(visit_dir / name))

    assert label_browse_collection_directory(str(collection_dir), 5167) == 2
    assert sorted(os.listdir(visit_dir)) == [
        'ld8x01010_x1dsum.png', 'ld8x01010_x1dsum.xml',
        'ld8x01010_x1dsum1.png', 'ld8x01010_x1dsum1.xml',
    ]
    # The previews share a collection but get distinct LIDs, each linked to the matching
    # x1dsum data product.
    for stem, prod_id in (('ld8x01010_x1dsum', 'ld8x01010'),
                          ('ld8x01010_x1dsum1', 'ld8x010101')):
        root = ET.parse(visit_dir / f'{stem}.xml').getroot()
        file_names = [e.text
                      for e in root.iterfind('.//pds:File/pds:file_name', PDS4_NS)]
        assert file_names == [f'{stem}.png']
        lids = [e.text for e in root.iterfind('.//pds:logical_identifier', PDS4_NS)]
        assert lids == [f'urn:nasa:pds:hst_05167:browse_cos_x1dsum:{prod_id}']
        refs = [e.text for e in root.iterfind('.//pds:lidvid_reference', PDS4_NS)]
        assert refs == [f'urn:nasa:pds:hst_05167:data_cos_x1dsum:{prod_id}::1.0']


def test_get_filtered_products_never_downloads_image_previews(monkeypatch):
    # A MAST product list with WFPC2, FOC, ACS, STIS, and FOS files and their previews:
    # the FITS files and the previews of spectra (FOS, STIS x1d) are kept, but no JPEG or
    # PNG preview of an image, whatever its suffix.
    filenames = ['u2xx0101t_c0m.fits', 'u2xx0101t_d0m.fits',
                 'u2xx0101t_c0f.jpg', 'u2xx0101t_d0f.jpg', 'u2xx0101t_drw.jpg',
                 'u2xx0101t_c0m.jpg', 'u2xx0101t_c0m.png',
                 'x34u0101t_c0f.fits', 'x34u0101t_c0f.jpg', 'x34u0101t_d0f.jpg',
                 'y3xx0101t_c0f.fits', 'y3xx0101t_c0f.jpg',
                 'j9xx01abq_drz.fits', 'j9xx01abq_drz.jpg',
                 'o4xx01abq_x1d.fits', 'o4xx01abq_x1d.png', 'o4xx01abq_flt.jpg']
    table = Table({'obs_id': [name.partition('_')[0] for name in filenames],
                   'productSubGroupDescription': [name.partition('_')[2]
                                                  .partition('.')[0].upper()
                                                  if name.endswith('.fits') else '--'
                                                  for name in filenames],
                   'productFilename': filenames})

    class FakeObservations:
        @staticmethod
        def get_product_list(observations):
            return observations

    monkeypatch.setattr(query_utils, 'Observations', FakeObservations)
    result = query_utils.get_filtered_products(table)
    assert sorted(result['productFilename']) == ['j9xx01abq_drz.fits',
                                                 'o4xx01abq_x1d.fits',
                                                 'o4xx01abq_x1d.png',
                                                 'u2xx0101t_c0m.fits',
                                                 'u2xx0101t_d0m.fits',
                                                 'x34u0101t_c0f.fits',
                                                 'y3xx0101t_c0f.fits',
                                                 'y3xx0101t_c0f.jpg']


def test_generate_picmaker_browse_products_skips_stis_spectra(tmp_path, monkeypatch):
    # STIS raw files are images only in imaging mode, e.g., target acquisitions; a
    # spectroscopic raw file gets no picmaker preview (its x1d gets MAST's plot instead).
    _use_tmp_staging(tmp_path, monkeypatch)
    data_dir = tmp_path / 'hst_05167' / 'data_stis_raw' / 'visit_01'
    os.makedirs(data_dir)
    for (name, obstype) in (('o4xx01aaq_raw.fits', 'IMAGING'),
                            ('o4xx01abq_raw.fits', 'SPECTROSCOPIC')):
        primary = pyfits.PrimaryHDU()
        primary.header['INSTRUME'] = 'STIS'
        primary.header['OBSTYPE'] = obstype
        pyfits.HDUList([primary]).writeto(data_dir / name)

    calls = []
    def fake_picmaker(**options):
        calls.append(os.path.basename(options['files'][0]))
        name = calls[-1].replace('.fits', '.jpg')
        _touch(os.path.join(options['directory'], name))

    monkeypatch.setattr(prepare_module, 'picmaker', fake_picmaker)
    assert prepare_module.generate_picmaker_browse_products(5167, '01') == 1
    assert calls == ['o4xx01aaq_raw.fits']
    assert os.listdir(tmp_path / 'hst_05167' / 'browse_stis_raw' / 'visit_01') == [
        'o4xx01aaq_raw.jpg'
    ]
